import type { MetadataRoute } from "next";

/**
 * Web app manifest: lets students install Starlight English to their phone's home screen
 * (Android "Install app" / iOS "Add to Home Screen"). It opens full-screen, without browser bars.
 * Icons are generated by `npm run assets:icons`.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Starlight English",
    short_name: "Starlight",
    description: "Year 7 English practice: novels, stories, poetry, grammar and spelling — one star at a time.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#0d1a2b",
    theme_color: "#0d1a2b",
    categories: ["education", "kids"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
      { src: "/icon.svg", sizes: "any", type: "image/svg+xml", purpose: "any" },
    ],
  };
}
